/*
 * speech_engine_k7.cpp
 *
 * sherpa-onnx implementation of include/voicelink/speech_engine.h for K7 + openvela.
 *
 * ASR: sherpa-onnx-offline-paraformer-zh (streaming bilingual also supported)
 * TTS: vits-icefall-zh-aishell3
 *
 * Audio I/O through NuttX PCM devices (ES8388 codec).
 * Model paths are compile-time defaults; override via voicelink_speech_config_t.
 */

#include "voicelink/speech_engine.h"

#include <cerrno>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fcntl.h>
#include <math.h>
#include <nuttx/audio/audio.h>
#include <pthread.h>
#include <sherpa-onnx/c-api/c-api.h>
#include <sys/ioctl.h>
#include <syslog.h>
#include <unistd.h>

/* -------------------------------------------------------------------------- */
/* Audio device paths (K7 + ES8388 BSP convention)                            */
/* -------------------------------------------------------------------------- */

#define AUDIO_OUT_DEV "/dev/audio/pcm/outp0"
#define AUDIO_INP_DEV "/dev/audio/pcm/inp0"

/* -------------------------------------------------------------------------- */
/* Compile-time model paths (override via Kconfig or environment)             */
/* -------------------------------------------------------------------------- */

#ifndef VOICELINK_TTS_MODEL_DIR
#define VOICELINK_TTS_MODEL_DIR "/data/voicelink/models/tts"
#endif
#ifndef VOICELINK_ASR_MODEL_DIR
#define VOICELINK_ASR_MODEL_DIR "/data/voicelink/models/asr"
#endif

/* -------------------------------------------------------------------------- */
/* Internal state                                                             */
/* -------------------------------------------------------------------------- */

static const SherpaOnnxOfflineTts* g_tts = nullptr;
static const SherpaOnnxOfflineRecognizer* g_recognizer = nullptr;
static pthread_mutex_t g_audio_lock = PTHREAD_MUTEX_INITIALIZER;
static volatile int g_stop_flag = 0;

/* -------------------------------------------------------------------------- */
/* voicelink_speech_init                                                      */
/* -------------------------------------------------------------------------- */

int voicelink_speech_init(void)
{
  /* --- TTS (vits-icefall-zh-aishell3) --- */

  SherpaOnnxOfflineTtsConfig tts_config;
  memset(&tts_config, 0, sizeof(tts_config));

  tts_config.model.vits.model =
      VOICELINK_TTS_MODEL_DIR "/model.onnx";
  tts_config.model.vits.tokens =
      VOICELINK_TTS_MODEL_DIR "/tokens.txt";
  tts_config.model.vits.dict_dir =
      VOICELINK_TTS_MODEL_DIR "/dict";
  tts_config.model.vits.length_scale = 1.0f;
  tts_config.model.vits.noise_scale = 0.667f;
  tts_config.model.vits.noise_scale_w = 0.8f;
  tts_config.model.num_threads = 2;
  tts_config.model.debug = 0;
  tts_config.model.provider = "cpu";
  tts_config.max_num_sentences = 1;
  tts_config.sid = 0;
  tts_config.sampling_rate = 16000;

  g_tts = SherpaOnnxOfflineTtsCreate(&tts_config);
  if (!g_tts) {
    syslog(LOG_ERR, "voicelink: TTS init failed "
           "(model: %s)\n", tts_config.model.vits.model);
    return -ENOENT;
  }

  /* --- ASR (sherpa-onnx-offline-paraformer-zh) --- */

  SherpaOnnxOfflineRecognizerConfig asr_config;
  memset(&asr_config, 0, sizeof(asr_config));

  asr_config.model_config.paraformer.model =
      VOICELINK_ASR_MODEL_DIR "/model.onnx";
  asr_config.model_config.tokens =
      VOICELINK_ASR_MODEL_DIR "/tokens.txt";
  asr_config.model_config.num_threads = 2;
  asr_config.model_config.debug = 0;
  asr_config.model_config.provider = "cpu";
  asr_config.decoding_method = "greedy_search";
  asr_config.max_active_paths = 4;
  asr_config.rule_fsts =
      VOICELINK_ASR_MODEL_DIR "/rule.fst,"
      VOICELINK_ASR_MODEL_DIR "/rule.far";

  g_recognizer = SherpaOnnxOfflineRecognizerCreate(&asr_config);
  if (!g_recognizer) {
    syslog(LOG_ERR, "voicelink: ASR init failed "
           "(model: %s)\n", asr_config.model_config.paraformer.model);
    SherpaOnnxOfflineTtsDestroy(g_tts);
    g_tts = nullptr;
    return -ENOENT;
  }

  g_stop_flag = 0;
  syslog(LOG_INFO, "voicelink: speech engine ready "
         "(TTS: vits-icefall-zh-aishell3, ASR: paraformer-zh)\n");
  return 0;
}

/* -------------------------------------------------------------------------- */
/* voicelink_speech_speak — synthesize and play through ES8388                 */
/* -------------------------------------------------------------------------- */

int voicelink_speech_speak(const char* utf8_text)
{
  if (!utf8_text || !g_tts) return -EINVAL;

  pthread_mutex_lock(&g_audio_lock);
  g_stop_flag = 0;

  const SherpaOnnxGeneratedAudio* audio =
      SherpaOnnxOfflineTtsGenerate(g_tts, utf8_text, 0, 0.8f);
  if (!audio || !audio->samples || audio->n == 0) {
    pthread_mutex_unlock(&g_audio_lock);
    syslog(LOG_ERR, "voicelink: TTS synthesis failed\n");
    return -EIO;
  }

  const int fd = open(AUDIO_OUT_DEV, O_WRONLY);
  if (fd < 0) {
    SherpaOnnxDestroyOfflineTtsGeneratedAudio(audio);
    pthread_mutex_unlock(&g_audio_lock);
    syslog(LOG_ERR, "voicelink: cannot open " AUDIO_OUT_DEV "\n");
    return -errno;
  }

  /* Configure PCM output: 16 kHz / 16-bit / mono */

  struct audio_caps_s caps;
  caps.ac_len = sizeof(caps);
  caps.ac_type = AUDIO_TYPE_OUTPUT;
  caps.ac_channels = 1;
  caps.ac_chmask = AUDIO_CHANNEL_MONO;
  caps.ac_samprate = audio->sample_rate;
  caps.ac_sampwidth = 16;
  ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&caps);

  /* Write samples in 40 ms chunks (640 frames @ 16 kHz) */

  const int16_t* samples = audio->samples;
  const int32_t total = (int32_t)audio->n;
  const int32_t chunk_frames = (int32_t)(audio->sample_rate * 40 / 1000);
  int32_t offset = 0;
  int ret = 0;

  while (offset < total && !g_stop_flag) {
    int32_t count = total - offset;
    if (count > chunk_frames) count = chunk_frames;
    const ssize_t written =
        write(fd, samples + offset, count * sizeof(int16_t));
    if (written < 0) {
      ret = -errno;
      break;
    }
    offset += (int32_t)(written / sizeof(int16_t));
  }

  close(fd);
  SherpaOnnxDestroyOfflineTtsGeneratedAudio(audio);
  pthread_mutex_unlock(&g_audio_lock);
  return ret;
}

/* -------------------------------------------------------------------------- */
/* voicelink_speech_stop                                                      */
/* -------------------------------------------------------------------------- */

int voicelink_speech_stop(void)
{
  g_stop_flag = 1;
  return 0;
}

/* -------------------------------------------------------------------------- */
/* voicelink_speech_recognize — record one utterance, run offline ASR          */
/* -------------------------------------------------------------------------- */

int voicelink_speech_recognize(enum voicelink_grammar grammar,
                                char* utf8_text, size_t capacity)
{
  if (!utf8_text || capacity == 0 || !g_recognizer)
    return -EINVAL;

  utf8_text[0] = '\0';

  pthread_mutex_lock(&g_audio_lock);

  /* Open microphone */

  const int fd = open(AUDIO_INP_DEV, O_RDONLY);
  if (fd < 0) {
    pthread_mutex_unlock(&g_audio_lock);
    syslog(LOG_ERR, "voicelink: cannot open " AUDIO_INP_DEV "\n");
    return -errno;
  }

  /* Configure PCM input: 16 kHz / 16-bit / mono */

  const uint32_t sample_rate = 16000;
  struct audio_caps_s caps;
  caps.ac_len = sizeof(caps);
  caps.ac_type = AUDIO_TYPE_INPUT;
  caps.ac_channels = 1;
  caps.ac_chmask = AUDIO_CHANNEL_MONO;
  caps.ac_samprate = sample_rate;
  caps.ac_sampwidth = 16;
  ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&caps);
  ioctl(fd, AUDIOIOC_START, 0);

  /* Record audio:
   * - Wake word: up to 3 s, stop early on 600 ms silence
   * - Network/password: up to 5 s, stop early on 800 ms silence
   * Silence threshold: RMS < 300 (16-bit scale)
   */

  const int is_wake = (grammar == VOICELINK_GRAMMAR_WAKE);
  const float max_seconds = is_wake ? 3.0f : 5.0f;
  const float silence_ms = is_wake ? 600.0f : 800.0f;
  const int32_t max_frames = (int32_t)(sample_rate * max_seconds);
  const int32_t silence_frames = (int32_t)(sample_rate * silence_ms / 1000);
  const int32_t chunk_frames = (int32_t)(sample_rate * 30 / 1000); /* 30 ms */

  int16_t* buf = (int16_t*)malloc(max_frames * sizeof(int16_t));
  if (!buf) {
    ioctl(fd, AUDIOIOC_STOP, 0);
    close(fd);
    pthread_mutex_unlock(&g_audio_lock);
    return -ENOMEM;
  }

  int32_t total = 0;
  int32_t trailing_silence = 0;
  int has_speech = 0;

  while (total < max_frames) {
    const int32_t want = max_frames - total;
    int32_t count = want < chunk_frames ? want : chunk_frames;
    const ssize_t n = read(fd, buf + total, count * sizeof(int16_t));
    if (n <= 0) break;
    const int32_t frames = (int32_t)(n / sizeof(int16_t));
    total += frames;

    /* Compute RMS for voice activity detection */

    int64_t sum_sq = 0;
    for (int32_t i = 0; i < frames; ++i)
      sum_sq += (int64_t)buf[total - frames + i] *
                buf[total - frames + i];
    const float rms = sqrtf((float)(sum_sq / frames));

    if (rms > 300.0f) {
      has_speech = 1;
      trailing_silence = 0;
    } else {
      trailing_silence += frames;
      if (has_speech && trailing_silence >= silence_frames)
        break; /* End of utterance */
    }

    /* Early exit: wake word timeout if no speech within 1.5 s */

    if (!has_speech && total > (int32_t)(sample_rate * 1.5f))
      break;
  }

  ioctl(fd, AUDIOIOC_STOP, 0);
  close(fd);

  /* If no speech detected, return timeout */

  if (!has_speech || total < (int32_t)(sample_rate * 0.1f)) {
    free(buf);
    pthread_mutex_unlock(&g_audio_lock);
    return VOICELINK_SPEECH_TIMEOUT;
  }

  /* Run offline ASR */

  const SherpaOnnxOfflineStream* stream =
      SherpaOnnxOfflineRecognizerCreateStream(g_recognizer);
  if (!stream) {
    free(buf);
    pthread_mutex_unlock(&g_audio_lock);
    return -EIO;
  }

  SherpaOnnxOfflineRecognizerAcceptWaveform(stream, sample_rate,
                                             buf, total);
  SherpaOnnxOfflineRecognizerDecode(stream);
  const SherpaOnnxOfflineRecognizerResult* result =
      SherpaOnnxOfflineRecognizerGetResult(stream);

  int ret;
  if (result && result->text && result->text[0] != '\0') {
    strncpy(utf8_text, result->text, capacity - 1);
    utf8_text[capacity - 1] = '\0';
    ret = VOICELINK_SPEECH_OK;
  } else {
    ret = VOICELINK_SPEECH_RETRY;
  }

  if (result) SherpaOnnxDestroyOfflineRecognizerResult(result);
  SherpaOnnxOfflineRecognizerDestroyStream(stream);
  free(buf);
  pthread_mutex_unlock(&g_audio_lock);
  return ret;
}

